window.REC_META = {"repo": "pasillo-seguro-unoq", "subtitle": "Movimiento, compensación global y riesgo en un solo binario", "description": "Recorrido por el pipeline en C que convierte un MJPEG de teléfono en un semáforo de riesgo: captura con resincronización JPEG, movimiento por bloques, compensación de cámara, componentes conexos, tracking y puntaje con histéresis.", "repo_url": "https://github.com/wanderc137/pasillo-seguro-unoq", "page_url": "https://wanderc137.github.io/pasillo-seguro-unoq/", "poster_text": "Recorrido por el pipeline en C que convierte un MJPEG de teléfono en un semáforo de riesgo: captura con resincronización JPEG, movimiento por bloques, compensación de cámara, componentes conexos, tracking y puntaje con histéresis.", "commands": ["make native", "make test", "./pasillo-seguro --camera http://192.168.1.9:8080/video", "make arm64", "./scripts/deploy_unoq.sh"], "chapters": [{"time": "0:06", "label": "EL PROBLEMA", "title": "Un pasillo necesita un semáforo, no un dataset"}, {"time": "0:20", "label": "ARQUITECTURA", "title": "Capturar, procesar, codificar y publicar"}, {"time": "0:36", "label": "CÁMARA", "title": "Resincronizar en vez de confiar en el socket"}, {"time": "0:52", "label": "MOVIMIENTO", "title": "Bloques de 8×8 y búsqueda de ±3 píxeles"}, {"time": "1:09", "label": "COMPENSACIÓN", "title": "Si la cámara se movió, se descuenta el movimiento global"}, {"time": "1:27", "label": "COMPONENTES", "title": "De la máscara a cajas con área y aspecto"}, {"time": "1:42", "label": "TRACKING", "title": "Velocidad, crecimiento y tiempo de colisión"}, {"time": "2:01", "label": "RIESGO", "title": "Seis señales, un solo número"}, {"time": "2:19", "label": "HISTÉRESIS", "title": "Evitar que el semáforo parpadee"}, {"time": "2:34", "label": "SEMÁFORO", "title": "El estado se dibuja sobre el vídeo"}, {"time": "2:49", "label": "STREAM", "title": "Cada cliente espera su frame, sin busy loop"}, {"time": "3:07", "label": "CÓMO EJECUTARLO", "title": "Compilar, apuntar a la cámara y abrir el puerto"}], "width": 104, "height": 34, "duration": 211.27, "title": "Pasillo Seguro · visión en C puro"};
